/** Compute Entrypoint Contract
  *
  * guarantee CASE_11_alarm_status_qualification
  * @param api_alarm_settings incoming data port
  * @param api_current_temperature incoming data port
  * @param api_interface_facts outgoing data port
  */
pub fn compute_spec_CASE_11_alarm_status_qualification_guarantee(
  api_alarm_settings: Isolette_Thermostat_Rust::AlarmTemperatureSettings,
  api_current_temperature: Isolette_Thermostat_Rust::CurrentTemperature,
  api_interface_facts: Isolette_Thermostat_Rust::MonitorInterfaceFacts) -> bool
{
  (api_interface_facts.interface_failure == !(api_alarm_settings.lower_valid) | !(api_alarm_settings.upper_valid)) &
    (api_interface_facts.current_valid == api_current_temperature.temperature_valid)
}

